interface User {
  name: string;
  email: string;
}

async function getUser() {
  try {
    // In a real application, you should use an absolute URL for server-side fetches.
    // We'll assume localhost:3000 for this example or fallback to mock data.
    const res = await fetch('http://localhost:3000/api/users/profile');
    if (!res.ok) {
      throw new Error('Failed to fetch user data');
    }
    return res.json();
  } catch (error) {
    // Fallback data as per pattern in page.tsx
    return {
      name: 'John Doe',
      email: 'john@example.com'
    };
  }
}

export default async function UserProfile() {
  const user: User = await getUser();

  return (
    <div>
      <h2>User Profile</h2>
      <div>Name: {user.name}</div>
      <div>Email: {user.email}</div>
    </div>
  );
}

